/* Handlers: return OK and fill the results, or an ERR_* for the client.
 * A NULL handler answers ERR_NOT_SUPPORTED. A `later` method's handler
 * also gets the request's txn, and may return IDL_LATER and answer it
 * with notify_reply_<method> (now, or later from anywhere). An event's
 * handler returns nothing (nothing is answered; a NULL one drops it),
 * owns the handles it is given, and its arrays point into the message. */
struct notify_ops {
    status_t (*notify)(void *ctx, const char *title, uint32_t title_len, const char *body, uint32_t body_len, uint8_t icon, uint8_t tint, const char *button1, uint32_t button1_len, const char *button2, uint32_t button2_len, const char *button3, uint32_t button3_len, uint32_t *out_id);
    status_t (*notify_wait)(void *ctx, struct idl_txn idl_txn, uint32_t *out_id, uint8_t *out_button);
    status_t (*withdraw)(void *ctx, uint32_t id);
    void (*post)(void *ctx, const char *title, uint32_t title_len, const char *body, uint32_t body_len, uint8_t icon, uint8_t tint);
};

/* Answer the notify.notify request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
static inline status_t notify_reply_notify(struct idl_txn idl_txn, status_t idl_st, uint32_t id)
{
    _Alignas(8) uint8_t idl_b0[12];
    struct notify_notify_rep *idl_r = (struct notify_notify_rep *)idl_b0;
    uint32_t idl_rn = sizeof(*idl_r);
    if (idl_st > 0)
        idl_st = ERR_INTERNAL;
    idl_r->id = id;
    idl_r->status = idl_st;
    if (idl_st != OK) {
        idl_rn = sizeof(struct idl_rep_hdr);
    }
    status_t idl_ws = idl_reply_write(idl_txn, idl_b0, idl_rn, NULL, 0);
    return idl_ws;
}

/* Answer the notify.notify_wait request kept in txn: idl_st and, if it is OK, the
 * results (handles are moved in every case: sent, or closed). A positive
 * status is ERR_INTERNAL, and so is OK with a handle result left
 * HANDLE_INVALID. Returns the write's status (idl_reply_write). */
